      "location": {
         "type": "string",
         "description": "The location to get the weather for",
         "required": false
      },
      "date_time": {
         "type": "string",
         "description": "The date and time to get the weather for",
         "required": false
      },
      "weather_unit": {
         "type": "string",
         "description": "The unit to use for the weather",
         "required": false
      },
      "weather_attribute": {
         "type": "string",
         "description": "weather related attributes mentioned in the query such as uv index, air quality, wind, humidity, etc.",
         "required": false
      }
   }
}
```
